http {
    user  nginx;
    worker_processes  1;
    error_log  /var/log/nginx/error.log warn;
    pid        /var/run/nginx.pid;

    client_temp_path /tmp/nginx_cache; # Redirect temporary files here

    server {
        listen 80;
        server_name  localhost;
        location / {
            root /usr/share/nginx/html;
            index index.html;
        }
    }
}'
"}

